import React, { useState, useRef, useEffect } from 'react';
import axios from 'axios';

function SeriesAIChatbot() {
  const [messages, setMessages] = useState([
    { role: 'assistant', content: 'Merhaba! Size dizi önerileri konusunda yardımcı olabilirim. Hangi tür dizileri seviyorsunuz veya hangi dizileri izlediniz?' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!input.trim()) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: userMessage }]);
    setIsLoading(true);

    try {
      // Hugging Face API'sini kullanarak yanıt al
      const response = await axios.post(
        'https://api-inference.huggingface.co/models/facebook/blenderbot-400M-distill',
        { inputs: `Dizi önerisi: ${userMessage}` },
        {
          headers: {
            'Authorization': 'Bearer hf_xxx', // Hugging Face API token'ınızı buraya ekleyin
            'Content-Type': 'application/json',
          },
        }
      );

      // API yanıtını işle
      let botResponse = '';
      if (response.data && response.data.generated_text) {
        botResponse = response.data.generated_text;
      } else {
        // Eğer API yanıt vermezse, basit bir yanıt oluştur
        botResponse = generateFallbackResponse(userMessage);
      }

      setMessages(prev => [...prev, { role: 'assistant', content: botResponse }]);
    } catch (error) {
      console.error('AI yanıtı alınırken hata oluştu:', error);
      // Hata durumunda basit bir yanıt oluştur
      const fallbackResponse = generateFallbackResponse(userMessage);
      setMessages(prev => [...prev, { role: 'assistant', content: fallbackResponse }]);
    } finally {
      setIsLoading(false);
    }
  };

  // API yanıt vermediğinde kullanılacak basit yanıtlar
  const generateFallbackResponse = (userMessage) => {
    const lowerMessage = userMessage.toLowerCase();
    
    if (lowerMessage.includes('aksiyon') || lowerMessage.includes('macera')) {
      return 'Aksiyon ve macera dizileri için "The Witcher", "Game of Thrones", "The Mandalorian" ve "Stranger Things" önerebilirim.';
    } else if (lowerMessage.includes('dram') || lowerMessage.includes('duygusal')) {
      return 'Dram dizileri için "This Is Us", "The Crown", "Breaking Bad" ve "The Handmaid\'s Tale" önerebilirim.';
    } else if (lowerMessage.includes('komedi') || lowerMessage.includes('güldürü')) {
      return 'Komedi dizileri için "The Office", "Friends", "Brooklyn Nine-Nine" ve "The Good Place" önerebilirim.';
    } else if (lowerMessage.includes('bilim kurgu') || lowerMessage.includes('sci-fi')) {
      return 'Bilim kurgu dizileri için "Black Mirror", "The Expanse", "Westworld" ve "Altered Carbon" önerebilirim.';
    } else if (lowerMessage.includes('gerilim') || lowerMessage.includes('thriller')) {
      return 'Gerilim dizileri için "Mindhunter", "True Detective", "Dark" ve "Ozark" önerebilirim.';
    } else if (lowerMessage.includes('suç') || lowerMessage.includes('polisiye')) {
      return 'Suç ve polisiye dizileri için "Breaking Bad", "Narcos", "Peaky Blinders" ve "Sherlock" önerebilirim.';
    } else if (lowerMessage.includes('fantastik') || lowerMessage.includes('fantasy')) {
      return 'Fantastik diziler için "Game of Thrones", "The Witcher", "The Lord of the Rings: The Rings of Power" ve "Shadow and Bone" önerebilirim.';
    } else if (lowerMessage.includes('anime')) {
      return 'Anime dizileri için "Attack on Titan", "Death Note", "Fullmetal Alchemist: Brotherhood" ve "Demon Slayer" önerebilirim.';
    } else if (lowerMessage.includes('belgesel') || lowerMessage.includes('documentary')) {
      return 'Belgesel dizileri için "Our Planet", "Planet Earth", "Making a Murderer" ve "The Last Dance" önerebilirim.';
    } else {
      return 'Size daha iyi öneriler sunabilmem için hangi tür dizileri sevdiğinizi veya hangi dizileri izlediğinizi belirtebilir misiniz? Örneğin: aksiyon, dram, komedi, bilim kurgu, gerilim, suç, fantastik, anime veya belgesel.';
    }
  };

  return (
    <div className="bg-white/90 backdrop-blur-sm rounded-xl shadow-lg overflow-hidden">
      <div className="p-4 bg-gradient-to-r from-purple-600 to-pink-600">
        <h3 className="text-lg font-semibold text-white">Dizi Öneri Asistanı</h3>
        <p className="text-sm text-white/80">Size dizi önerileri konusunda yardımcı olabilirim</p>
      </div>
      
      <div className="h-80 overflow-y-auto p-4">
        {messages.map((message, index) => (
          <div 
            key={index} 
            className={`mb-4 ${message.role === 'user' ? 'text-right' : 'text-left'}`}
          >
            <div 
              className={`inline-block p-3 rounded-lg max-w-[80%] ${
                message.role === 'user' 
                  ? 'bg-purple-600 text-white' 
                  : 'bg-gray-100 text-gray-800'
              }`}
            >
              {message.content}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="text-left mb-4">
            <div className="inline-block p-3 rounded-lg bg-gray-100 text-gray-800">
              <div className="flex space-x-2">
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.4s' }}></div>
              </div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>
      
      <form onSubmit={handleSubmit} className="p-4 border-t border-gray-200">
        <div className="flex">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Dizi önerisi isteyin..."
            className="flex-1 p-2 border border-gray-300 rounded-l-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
            disabled={isLoading}
          />
          <button
            type="submit"
            className="px-4 py-2 bg-gradient-to-r from-purple-600 to-pink-600 text-white rounded-r-lg hover:from-purple-700 hover:to-pink-700 transition duration-200 disabled:opacity-50"
            disabled={isLoading || !input.trim()}
          >
            Gönder
          </button>
        </div>
      </form>
    </div>
  );
}

export default SeriesAIChatbot;
